$(document).ready(function() {
    const $dataKopi = {
        "kopi-pancong": { 
            harga: "Rp 8.000", 
            deskripsi: "Kopi khas Sumatra yang disajikan hanya setengah gelas (dipancung). Rasanya pekat dan ukurannya pas untuk dinikmati dengan cepat." 
        },
        "kopi-joss": {
            harga: "Rp 10.000",
            deskripsi: "Kopi yang terkenal dengan rasa yang kental dan kuat. Cocok untuk mereka yang menyukai kopi dengan rasa yang lebih intens."
        },
        "kopi-khop": { 
            harga: "Rp 12.000", 
            deskripsi: "Kopi pesisir Aceh Barat yang disajikan dengan gelas terbalik di atas piring kecil. Dinikmati dengan cara ditiup dan diseruput perlahan melalui sedotan." 
        },
        "kopi-tubruk": {
            harga: "Rp 15.000",
            deskripsi: "Kopi tradisional yang disajikan dengan cara menambahkan gula merah dan air mendidih ke dalam gelas. Rasanya manis dan kental."
        },
        "kopi-rarobang": { 
            harga: "Rp 20.000", 
            deskripsi: "Kopi rempah tradisional Ambon yang diseduh bersama jahe, cengkeh, dan kayu manis, lalu disajikan dengan taburan irisan kacang kenari yang gurih." 
        }
    };

    $('.btn-detail').on('click', function() {
        const idKopi = $(this).attr('id');
        const detail = $dataKopi[idKopi];
        const $wadahInfo = $('#info-' + idKopi);

        if (detail && $wadahInfo.length) {
            $wadahInfo.find('.harga-text').text(detail.harga);
            $wadahInfo.find('.deskripsi-text').text(detail.deskripsi);

            if ($wadahInfo.is(':visible')) {
                $wadahInfo.hide();
                $(this).text('Learn more');
            } else {
                $wadahInfo.show();
                $(this).text('Show less');
            }
        } else {
            return;
        }
    });

    $('.accordion').on('click', function() {
        $(this).toggleClass('active');
        const $panel = $(this).next();
        if ($panel.css('max-height') !== '0px') {
            $panel.css('max-height', '0px');
        } else {
            $panel.css('max-height', $panel.prop('scrollHeight') + 'px');
        }
    });
});